<section class="form-section"><div class="form-section-heading"><h2>Organization details</h2></div><div class="form-grid"><div class="form-field span-2"><label for="name">Organization name *</label><input id="name" name="name" maxlength="255" required value="<?=View::escape($value('name'))?>"></div><div class="form-field span-2"><label for="slug">URL name</label><input id="slug" name="slug" maxlength="280" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value="<?=View::escape($value('slug'))?>"><p class="field-guidance">Leave blank to generate it from the organization name.</p></div><div class="form-field"><label for="partner_type">Organization type</label><select id="partner_type" name="partner_type"><?php foreach ($partnerTypes as $type): ?><option value="<?=View::escape($type)?>"<?=$value('partner_type')===$type?' selected':''?>><?=View::escape(ucwords(str_replace('_',' ',$type)))?></option><?php endforeach; ?></select></div><div class="form-field"><label for="country">Country</label><input id="country" name="country" maxlength="100" value="<?=View::escape($value('country'))?>"></div><div class="form-field span-2"><label for="website_url">Website</label><input id="website_url" name="website_url" type="url" maxlength="500" placeholder="https://" value="<?=View::escape($value('website_url'))?>"></div><div class="form-field span-2"><label for="description">Description</label><textarea id="description" name="description" rows="7"><?=View::escape($value('description'))?></textarea></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Partner logo</h2><p>Reuse an active catalogue image or upload a new logo.</p></div><div class="form-grid"><div class="form-field span-2"><label for="logo_media_id">Existing image</label><select id="logo_media_id" name="logo_media_id"><option value="">No logo</option><?php foreach ($images as $image): ?><option value="<?=(int)$image['id']?>"<?=$value('logo_media_id')===(string)$image['id']?' selected':''?>><?=View::escape($image['original_name'])?></option><?php endforeach; ?></select></div><div class="form-field span-2"><label for="partner_logo">Upload logo</label><input id="partner_logo" name="partner_logo" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><p class="field-guidance">JPEG, PNG, WebP, or GIF; maximum 20 MB.</p></div><div class="form-field span-2"><label for="logo_alt_text">Logo description</label><input id="logo_alt_text" name="logo_alt_text" maxlength="255" placeholder="Required for a new upload"></div></div></section>
